// 売上データの詳細分析処理
const items = $input.all();
const currentDate = new Date();
const reportDate = currentDate.toISOString().split('T')[0];

// ユーティリティ関数
function formatCurrency(amount) {
  return new Intl.NumberFormat('ja-JP', {
    style: 'currency',
    currency: 'JPY'
  }).format(amount);
}

function formatDate(dateStr) {
  try {
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  } catch {
    return dateStr;
  }
}

// データ初期化
let totalSales = 0;
let totalQuantity = 0;
let totalOrders = 0;
const productData = {};
const categoryData = {};
const salesPersonData = {};
const dailyData = {};
const weeklyData = {};

// データ処理とバリデーション
items.forEach((item, index) => {
  const data = item.json;

  // データバリデーション
  const date = data['日付'] || data.date || reportDate;
  const product = (data['商品名'] || data.product || '不明商品').toString().trim();
  const amount = parseFloat(data['売上金額'] || data.amount || 0);
  const quantity = parseInt(data['数量'] || data.quantity || 0);
  const category = (data['カテゴリ'] || data.category || 'その他').toString().trim();
  const salesPerson = (data['担当者'] || data.sales_person || '不明').toString().trim();

  // 無効なデータをスキップ
  if (amount <= 0 || quantity <= 0) {
    console.log(`スキップ: 行${index + 1} - 無効なデータ`);
    return;
  }

  // 基本集計
  totalSales += amount;
  totalQuantity += quantity;
  totalOrders++;

  // 商品別集計
  if (!productData[product]) {
    productData[product] = {
      name: product,
      totalAmount: 0,
      totalQuantity: 0,
      orderCount: 0,
      avgPrice: 0
    };
  }
  productData[product].totalAmount += amount;
  productData[product].totalQuantity += quantity;
  productData[product].orderCount++;
  productData[product].avgPrice = productData[product].totalAmount / productData[product].totalQuantity;

  // カテゴリ別集計
  if (!categoryData[category]) {
    categoryData[category] = {
      name: category,
      totalAmount: 0,
      totalQuantity: 0,
      orderCount: 0,
      products: new Set()
    };
  }
  categoryData[category].totalAmount += amount;
  categoryData[category].totalQuantity += quantity;
  categoryData[category].orderCount++;
  categoryData[category].products.add(product);

  // 担当者別集計
  if (!salesPersonData[salesPerson]) {
    salesPersonData[salesPerson] = {
      name: salesPerson,
      totalAmount: 0,
      totalQuantity: 0,
      orderCount: 0,
      avgOrderValue: 0
    };
  }
  salesPersonData[salesPerson].totalAmount += amount;
  salesPersonData[salesPerson].totalQuantity += quantity;
  salesPersonData[salesPerson].orderCount++;
  salesPersonData[salesPerson].avgOrderValue = salesPersonData[salesPerson].totalAmount / salesPersonData[salesPerson].orderCount;

  // 日別集計
  if (!dailyData[date]) {
    dailyData[date] = {
      date: formatDate(date),
      totalAmount: 0,
      totalQuantity: 0,
      orderCount: 0,
      uniqueProducts: new Set()
    };
  }
  dailyData[date].totalAmount += amount;
  dailyData[date].totalQuantity += quantity;
  dailyData[date].orderCount++;
  dailyData[date].uniqueProducts.add(product);
});

// ランキング生成
const topProducts = Object.values(productData)
  .sort((a, b) => b.totalAmount - a.totalAmount)
  .slice(0, 10)
  .map((item, index) => ({
    rank: index + 1,
    name: item.name,
    amount: Math.round(item.totalAmount),
    quantity: item.totalQuantity,
    orderCount: item.orderCount,
    avgPrice: Math.round(item.avgPrice),
    sharePercent: ((item.totalAmount / totalSales) * 100).toFixed(1)
  }));

const topSalesPeople = Object.values(salesPersonData)
  .sort((a, b) => b.totalAmount - a.totalAmount)
  .slice(0, 10)
  .map((item, index) => ({
    rank: index + 1,
    name: item.name,
    amount: Math.round(item.totalAmount),
    quantity: item.totalQuantity,
    orderCount: item.orderCount,
    avgOrderValue: Math.round(item.avgOrderValue),
    sharePercent: ((item.totalAmount / totalSales) * 100).toFixed(1)
  }));

const categoryAnalysis = Object.values(categoryData)
  .sort((a, b) => b.totalAmount - a.totalAmount)
  .map((item, index) => ({
    rank: index + 1,
    name: item.name,
    amount: Math.round(item.totalAmount),
    quantity: item.totalQuantity,
    orderCount: item.orderCount,
    productCount: item.products.size,
    sharePercent: ((item.totalAmount / totalSales) * 100).toFixed(1)
  }));

// 日別データ（直近14日）
const recentDailyData = Object.values(dailyData)
  .map(item => ({
    ...item,
    amount: Math.round(item.totalAmount),
    uniqueProductCount: item.uniqueProducts.size
  }))
  .sort((a, b) => new Date(b.date) - new Date(a.date))
  .slice(0, 14);

// KPI計算
const avgDailySales = totalSales / Object.keys(dailyData).length;
const avgOrderValue = totalSales / totalOrders;
const avgOrderQuantity = totalQuantity / totalOrders;
const totalProductTypes = Object.keys(productData).length;

// 成長率分析（過去7日 vs その前7日）
const sortedDays = Object.keys(dailyData).sort();
const recentWeekSales = sortedDays.slice(-7).reduce((sum, date) => sum + dailyData[date].totalAmount, 0);
const previousWeekSales = sortedDays.slice(-14, -7).reduce((sum, date) => sum + dailyData[date].totalAmount, 0);
const weeklyGrowthRate = previousWeekSales > 0 ? ((recentWeekSales - previousWeekSales) / previousWeekSales * 100).toFixed(1) : 0;

// アラート生成
const alerts = [];
if (weeklyGrowthRate < -10) {
  alerts.push({
    type: 'warning',
    message: `売上が前週比${Math.abs(weeklyGrowthRate)}%減少しています`,
    action: '売上動向の詳細分析を推奨'
  });
} else if (weeklyGrowthRate > 20) {
  alerts.push({
    type: 'success',
    message: `売上が前週比${weeklyGrowthRate}%増加しています`,
    action: '好調要因の分析と継続施策を検討'
  });
}

if (avgOrderValue < 50000) {
  alerts.push({
    type: 'info',
    message: '平均注文額が低めです',
    action: 'アップセル・クロスセル施策を検討'
  });
}

// 最終結果
return [{
  json: {
    reportGenerated: new Date().toISOString(),
    reportDate: reportDate,
    summary: {
      totalSales: Math.round(totalSales),
      totalQuantity: totalQuantity,
      totalOrders: totalOrders,
      avgDailySales: Math.round(avgDailySales),
      avgOrderValue: Math.round(avgOrderValue),
      avgOrderQuantity: Math.round(avgOrderQuantity),
      totalProductTypes: totalProductTypes,
      weeklyGrowthRate: parseFloat(weeklyGrowthRate)
    },
    rankings: {
      topProducts: topProducts,
      topSalesPeople: topSalesPeople,
      categoryAnalysis: categoryAnalysis
    },
    trends: {
      recentDailyData: recentDailyData,
      recentWeekSales: Math.round(recentWeekSales),
      previousWeekSales: Math.round(previousWeekSales)
    },
    alerts: alerts,
    metadata: {
      processedRecords: items.length,
      validRecords: totalOrders,
      processingTime: Date.now()
    }
  }
}];
